/* Huisstijlletters voor het PDF-dossier - GEGENEREERD BESTAND.
 * Niet met de hand bijwerken: dit komt uit tools/bouw-dossier-fonts.py,
 * dat de woff2-bestanden van de site subset en omzet naar TTF.
 * Bron: Inter, Instrument Serif, IBM Plex Mono (alle drie OFL).
 */
(function (global) {
  "use strict";
  var FONTS = [
    ["Inter-Regular.ttf", "Inter", "normal", ""],
    ["Inter-SemiBold.ttf", "Inter", "bold", ""],
    ["InstrumentSerif-Regular.ttf", "InstrumentSerif", "normal", ""],
    ["InstrumentSerif-Italic.ttf", "InstrumentSerif", "italic", ""],
    ["IBMPlexMono-Regular.ttf", "IBMPlexMono", "normal", ""],
  ];
  /* jsPDF leest fonts per document; registreren gebeurt via de API-hook,
     dan geldt het voor elk document dat daarna wordt aangemaakt. */
  function registreer() {
    if (!global.jspdf || !global.jspdf.jsPDF) return false;
    var API = global.jspdf.jsPDF.API;
    FONTS.forEach(function (f) {
      API.events.push(['addFonts', function () {
        this.addFileToVFS(f[0], f[3]);
        this.addFont(f[0], f[1], f[2]);
      }]);
    });
    return true;
  }
  if (!registreer()) {
    /* jsPDF laadt met defer; dan haken we in zodra het er is */
    global.addEventListener('load', registreer);
  }
  global.NGDossierFonts = { geregistreerd: registreer };
})(typeof window !== "undefined" ? window : globalThis);
